<script>(function(){var s=document.getElementById('product_id'),w=document.getElementById('product-select'),t=w.querySelector('.mp-select-trigger'),list=w.querySelector('.mp-select-options');Array.prototype.forEach.call(s.options,function(o){var x=document.createElement('div');x.className='mp-select-option'+(o.selected?' active':'');x.textContent=o.textContent;x.addEventListener('click',function(){s.value=o.value;s.dispatchEvent(new Event('change',{bubbles:true}));t.textContent=o.textContent;w.classList.remove('open');list.querySelectorAll('.mp-select-option').forEach(function(y){y.classList.toggle('active',y===x)});});list.appendChild(x)});t.addEventListener('click',function(){w.classList.toggle('open')});document.addEventListener('click',function(e){if(!w.contains(e.target))w.classList.remove('open')});})();</script></body></html>
